#include <stdio.h>
#include <string.h>
#include <ctype.h>

static int is_leap(int y)
{
    return (y % 4 == 0) && ( (y % 100 != 0) || (y % 400 == 0) );
}

static int days_in_month(int m, int y)
{
    static const int dim[12] = {31,28,31,30,31,30,31,31,30,31,30,31};
    if (m == 2 && is_leap(y)) return 29;
    return dim[m-1];
}

int main(int argc, char *argv[])
{
    if (argc < 2) { puts("INVALID"); return 0; }
    const char *s = argv[1];
    if (strlen(s) != 10) { puts("INVALID"); return 0; }
    if (s[4] != '-' || s[7] != '-') { puts("INVALID"); return 0; }
    for (int i=0;i<10;i++) if (i!=4 && i!=7 && !isdigit((unsigned char)s[i])) { puts("INVALID"); return 0; }
    int year = (s[0]-'0')*1000 + (s[1]-'0')*100 + (s[2]-'0')*10 + (s[3]-'0');
    int month = (s[5]-'0')*10 + (s[6]-'0');
    int day = (s[8]-'0')*10 + (s[9]-'0');
    if (month<1 || month>12) { puts("INVALID"); return 0; }
    if (day<1 || day>days_in_month(month,year)) { puts("INVALID"); return 0; }
    puts("VALID");
    return 0;
}
